import {parseVersion} from './version.mjs';
export function createCatalog(seed=[]) {
  const entries=new Map(seed.map(r=>[r.id,r]));
  const api={list:()=>[...entries.values()],get:id=>entries.get(id)??null,
    add:r=>{parseVersion(r.version);entries.set(r.id,r);return r;},
    update:(id,patch)=>{const r={...entries.get(id),...patch};entries.set(id,r);return r;},
    remove:id=>entries.delete(id),applyBatch:operations=>operations.map(op=>{
      if(op.type==='add')return api.add(op.record);if(op.type==='update')return api.update(op.id,op.patch);
      if(op.type==='remove')return api.remove(op.id);throw Error('invalid operation');
    })};return api;
}

export function parseVersion(text) {
  const [base,pre]=text.split('-'); const [major,minor,patch]=base.split('.').map(Number);
  if ([major,minor,patch].some(n=>!Number.isInteger(n)||n<0)) throw Error('invalid version');
  return {major,minor,patch,prerelease:pre?pre.split('.'):[]};
}
export function compareVersions(a,b) { return a===b?0:a<b?-1:1; }

import test from 'node:test';import assert from 'node:assert/strict';
import {parseCSV,stringifyCSV} from '../src/csv.mjs';import {compareVersions} from '../src/version.mjs';import {createCatalog} from '../src/catalog.mjs';
test('plain CSV',()=>assert.deepEqual(parseCSV(stringifyCSV([['a','b'],['c','d']])),[['a','b'],['c','d']]));
test('equal versions',()=>assert.equal(compareVersions('1.2.3','1.2.3'),0));
test('store one record',()=>assert.equal(createCatalog([{id:'a',name:'A',version:'1.0.0',tags:[],dependencies:[]}]).get('a').name,'A'));

